class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0

        # Try all possible subarrays [i, j] where i <= j
        for i in range(n):
            for j in range(i, n):
                # Check if removing subarray [i, j] leaves a strictly increasing array
                ok = True
                lst = -1  # This will store the last seen value in the remaining array

                # Iterate through all positions k
                for k in range(n):
                    if i <= k <= j:
                        # Skip elements in the subarray being removed
                        continue
                    else:
                        # Check if current element maintains strictly increasing property
                        if lst != -1 and lst >= nums[k]:
                            ok = False
                            break
                        lst = nums[k]

                if ok:
                    ans += 1

        return ans

