class Solution:
    def findPeaks(self, mountain: List[int]) -> List[int]:
        res = []
        for i in range(1, len(mountain) - 1):
            if mountain[i] > mountain[i-1] and mountain[i] > mountain[i+1]:
                res.append(i)
        return res

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        m = len(mat)
        n = len(mat[0])

        # Create a copy of the original matrix to work with
        shifted_mat = [row[:] for row in mat]

        # Apply shifts to each row
        for i in range(m):
            if i % 2 == 0:  # even indexed row (0-indexed)
                # Left shift k times
                for _ in range(k):
                    first_element = shifted_mat[i][0]
                    shifted_mat[i] = shifted_mat[i][1:] + [first_element]
            else:  # odd indexed row
                # Right shift k times
                for _ in range(k):
                    last_element = shifted_mat[i][-1]
                    shifted_mat[i] = [last_element] + shifted_mat[i][:-1]

        # Check if shifted matrix equals original matrix
        return shifted_mat == mat

