class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        # Get lengths of all three strings
        lengths = [len(s1), len(s2), len(s3)]

        # Find minimum length
        minimum_length = min(lengths)

        # Initialize count of common prefix characters
        count = 0

        # Check each position from 0 to minimum_length - 1
        for i in range(minimum_length):
            if s1[i] == s2[i] == s3[i]:
                count += 1
            else:
                break

        # If no common prefix found
        if count == 0:
            return -1

        # Calculate minimum operations needed
        # Total characters to remove = sum of lengths - 3 * count
        return sum(lengths) - 3 * count

