class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)

        for start in range(n):
            for end in range(start, n):
                x = nums[start]
                y = nums[end]

                # Check if it's a strong pair
                if abs(x - y) <= min(x, y):
                    current_xor = x ^ y
                    max_xor = max(max_xor, current_xor)

        return max_xor

