class Solution:
    def findIndices(self, nums: List[int], indexDifference: int, valueDifference: int) -> List[int]:
        n = len(nums)

        # Special case: if both differences are zero, return [0, 0]
        if indexDifference == 0 and valueDifference == 0:
            return [0, 0]

        # Iterate through all possible i values
        for i in range(n):
            # Initialize j to i
            j = i

            # Check all possible j values starting from i
            while j < n:
                # Check if both conditions are satisfied
                if abs(i - j) >= indexDifference and abs(nums[i] - nums[j]) >= valueDifference:
                    return [i, j]

                # Increment j
                j += 1

        # No valid pair found
        return [-1, -1]

