class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        visited = []  # to store all visited integers
        ans = []      # to store the result
        consecutive_prev_count = 0  # count of consecutive "prev" strings

        for word in words:
            if word == "prev":
                # Check if we have enough integers
                if consecutive_prev_count == 0:
                    ans.append(-1)
                else:
                    # We want the (consecutive_prev_count - 1)th element from the end
                    # Since we want the (k-1)th index in nums_reverse
                    # nums_reverse[k-1] means we want the element at position k-1 from the end
                    # which is at index len(visited) - k in the original array
                    # Actually, since nums_reverse[k-1] corresponds to the element at position (len(visited) - k) in the original array
                    # But simpler: we can just get the element at index (consecutive_prev_count - 1) from the end
                    # That is: visited[len(visited) - consecutive_prev_count]
                    if consecutive_prev_count <= len(visited):
                        ans.append(visited[len(visited) - consecutive_prev_count])
                    else:
                        ans.append(-1)
                consecutive_prev_count += 1
            else:
                # Convert to integer and add to visited
                visited.append(int(word))
                consecutive_prev_count = 0  # reset consecutive prev count

        return ans

