class Solution:
    def differenceOfSums(self, n: int, m: int) -> int:
        div_by_m = []
        n_div_by_m = []

        for i in range(1, n + 1):
            if i % m == 0:
                div_by_m.append(i)
            else:
                n_div_by_m.append(i)

        sum_n_div_by_m = sum(n_div_by_m)
        sum_div_by_m = sum(div_by_m)

        return sum_n_div_by_m - sum_div_by_m

