class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # We need to collect numbers 1, 2, ..., k
        # Process from right to left (last element first)
        collected = set()
        operations = 0

        # Start from the end of the array
        for i in range(len(nums) - 1, -1, -1):
            # Check if the current number is in range [1, k]
            if 1 <= nums[i] <= k:
                collected.add(nums[i])
                operations += 1
                if len(collected) == k:
                    return operations

        return operations

