class Solution:
    def countSymmetricIntegers(self, low: int, high: int) -> int:
        ans = 0
        for i in range(low, high + 1):
            s = str(i)
            if len(s) % 2 != 0:
                continue

            n = len(s) // 2
            a = int(s[:n])
            b = int(s[n:])

            s1, s2 = 0, 0
            temp_a, temp_b = a, b

            while temp_a != 0:
                s1 += temp_a % 10
                temp_a //= 10

            while temp_b != 0:
                s2 += temp_b % 10
                temp_b //= 10

            if s1 == s2:
                ans += 1

        return ans

