class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        temp = [(0, 0)]  # (position, cost)

        for i in range(len(prices)):
            pos = 2 * i + 2
            new_cost = temp[0][1] + prices[i]

            # Remove first element if i equals its position
            if i == temp[0][0]:
                temp.pop(0)

            # While temp is not empty, check if last element's cost >= new_cost
            while temp and temp[-1][1] >= new_cost:
                temp.pop()

            # Append the new offer
            temp.append((pos, new_cost))

        return temp[0][1]

