class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        # Initialize winner as a set of all teams from 0 to n-1
        winner = set(range(n))

        # For each edge in edges
        for edge in edges:
            # Discard the weaker team (edge[1])
            winner.discard(edge[1])

        # If length of winner > 1, return -1 (no unique champion)
        if len(winner) > 1:
            return -1

        # If exactly one team remains, return it as the champion
        for team in winner:
            return team

        # This should not be reached if winner is valid
        return -1

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        s1 = sum(nums1)
        z1 = nums1.count(0)
        s2 = sum(nums2)
        z2 = nums2.count(0)

        if z1 == 0 and z2 == 0:
            return s1 if s1 == s2 else -1
        elif z1 == 0 and z2 > 0:
            return s1 if s1 >= s2 + z2 else -1
        elif z1 > 0 and z2 == 0:
            return s2 if s2 >= s1 + z1 else -1
        else:  # both have zeros
            return max(s1 + z1, s2 + z2)

