class Solution:
    def minIncrementOperations(self, nums: List[int], k: int) -> int:
        # Initialize dp array with three zeros
        dp = [0, 0, 0]

        # Process each number in the array
        for num in nums:
            # Update dp: new_dp[0] = old_dp[1], new_dp[1] = old_dp[2], 
            # new_dp[2] = max(k - num, 0) + min(old_dp)
            new_dp = [dp[1], dp[2], max(k - num, 0) + min(dp)]
            dp = new_dp

        # Return the minimum value among the three states
        return min(dp)

