class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        m = len(grid[0])

        # Calculate total product
        total_product = 1
        for i in range(n):
            for j in range(m):
                total_product = (total_product * grid[i][j]) % 12345

        result = [[0] * m for _ in range(n)]

        # For each position, calculate product excluding current element
        for i in range(n):
            for j in range(m):
                # We need to compute product of all other elements
                # Instead of dividing, we'll reconstruct it

                # Calculate product excluding grid[i][j]
                product_excluding_current = 1
                for x in range(n):
                    for y in range(m):
                        if x == i and y == j:
                            continue
                        product_excluding_current = (product_excluding_current * grid[x][y]) % 12345

                result[i][j] = product_excluding_current

        return result

