class Solution:
    def minOperations(self, nums: List[int]) -> int:
        from collections import Counter

        freq = Counter(nums)
        count = 0

        for f in freq.values():
            if f == 1:
                return -1
            count += f // 3
            if f % 3 == 1 or f % 3 == 2:
                count += 1

        return count

