completion:
class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        # Calculate the overall AND of all elements
        m = nums[0]
        for i in range(1, len(nums)):
            m &= nums[i]

        # If overall AND is not 0, we can't split further (any split would increase sum)
        if m != 0:
            return 1

        # Otherwise, greedily form subarrays with AND equal to 0
        count = 0
        s = nums[0]
        for i in range(len(nums)):
            s &= nums[i]
            if s == 0:
                count += 1
                s = nums[i] if i < len(nums) - 1 else 0  # Reset s for next subarray

        return count

