class Solution:
    def canMakeSubsequence(self, str1: str, str2: str) -> bool:
        n, m = len(str1), len(str2)
        i, j = 0, 0

        while i < n and j < m:
            # Check if current character in str2 can match current character in str1
            # or the next character cyclically
            if str1[i] == str2[j] or chr(ord(str1[i]) + 1) == str2[j] or (ord(str1[i]) - ord('a') + 1) % 26 == ord(str2[j]) - ord('a'):
                # Actually, simpler: check if str2[j] is either str1[i] or the next character cyclically
                if str1[i] == str2[j] or chr((ord(str1[i]) - ord('a') + 1) % 26 + ord('a')) == str2[j]:
                    j += 1
            i += 1

        return j == m

