            j = bisect.bisect_left(S, nums[i])

            # Check if there's an element at position j
            if j < len(S):
                res = min(res, abs(S[j] - nums[i]))

            # Check if there's an element at position j-1
            if j > 0:
                res = min(res, abs(S[j-1] - nums[i]))

            # Add nums[i-(x-1)] to S if i >= x-1
            if i >= x - 1:
                bisect.insort(S, nums[i - (x - 1)])

        return res

