class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        # If array length is <= 2, it can always be split
        if n <= 2:
            return True

        # Check if there exists any adjacent pair with sum >= m
        for i in range(n - 1):
            if nums[i] + nums[i + 1] >= m:
                return True

        # If no such pair exists, it's impossible to split
        return False

