class Solution:
    def sortVowels(self, s: str) -> str:
        vowels = set('AEIOUaeiou')
        # Count frequency of each vowel
        vowel_count = {}
        for char in s:
            if char in vowels:
                vowel_count[char] = vowel_count.get(char, 0) + 1

        # Create list of vowel-count pairs sorted by ASCII value
        h = []
        for vowel in sorted(vowel_count.keys()):
            h.append([vowel, vowel_count[vowel]])

        ans = []
        i = 0  # index for h list

        for char in s:
            if char in vowels:
                # Use the vowel from h[i]
                ans.append(h[i][0])
                h[i][1] -= 1
                if h[i][1] == 0:
                    i += 1
            else:
                ans.append(char)

        return ''.join(ans)

