class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        n = len(nums)

        # Find the dominant element of the entire array
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Find the dominant element (the one that satisfies freq * 2 > n)
        dominant = None
        for num, count in freq.items():
            if count * 2 > n:
                dominant = num
                break

        # Now check each possible split index
        for i in range(n - 1):  # i from 0 to n-2
            # Count frequency of dominant element in left part [0...i]
            left_freq = 0
            for j in range(i + 1):
                if nums[j] == dominant:
                    left_freq += 1

            # Count frequency of dominant element in right part [i+1...n-1]
            right_freq = 0
            for j in range(i + 1, n):
                if nums[j] == dominant:
                    right_freq += 1

            # Check if both parts have the dominant element as their own dominant element
            left_len = i + 1
            right_len = n - i - 1

            if left_freq * 2 > left_len and right_freq * 2 > right_len:
                return i

        return -1

