                suffix_ok = True
                for k in range(j + 1, n):
                    if nums[k] <= nums[k - 1]:
                        suffix_ok = False
                        break

                # Check connection between prefix and suffix
                if i == 0 and j == n:
                    # Removing everything - empty array is strictly increasing
                    count += 1
                elif i == 0:
                    # Only suffix remains
                    if j < n:
                        count += 1
                elif j == n:
                    # Only prefix remains
                    if i > 0:
                        count += 1
                else:
                    # Both prefix and suffix remain
                    if i > 0 and j < n:
                        if nums[i - 1] < nums[j]:
                            count += 1

