class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Try every possible subarray to remove
        for i in range(n):
            for j in range(i, n):
                # Remove subarray from index i to j
                # Check if remaining elements are strictly increasing
                remaining = []
                # Add elements before the subarray
                for k in range(i):
                    remaining.append(nums[k])
                # Add elements after the subarray
                for k in range(j + 1, n):
                    remaining.append(nums[k])

                # Check if remaining array is strictly increasing
                is_increasing = True
                for k in range(1, len(remaining)):
                    if remaining[k] <= remaining[k - 1]:
                        is_increasing = False
                        break

                if is_increasing:
                    count += 1

        return count

