class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        # Create a dictionary mapping each number to its last occurrence index
        last = {}
        for i, x in enumerate(nums):
            last[x] = i

        ii = -1  # right boundary of current partition
        p = -1   # count of separators we can place

        for i, x in enumerate(nums):
            # Update the right boundary to include the last occurrence of current number
            ii = max(ii, last[x])

            # If current position is beyond the right boundary of current partition,
            # we can place a separator here
            if ii < i:
                p += 1

        # Return 2^p mod (10^9 + 7)
        return pow(2, p, 1_000_000_007)

