class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0

        # Generate all possible pairs (including same element twice)
        for i in range(len(nums)):
            for j in range(len(nums)):
                x, y = nums[i], nums[j]

                # Check if this is a strong pair
                if abs(x - y) <= min(x, y):
                    # Update maximum XOR
                    max_xor = max(max_xor, x ^ y)

        return max_xor

