import math
from collections import defaultdict

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        # Helper function to get square-free part of a number
        def get_square_free_part(num):
            # Remove all squared factors
            temp = num
            d = 2
            while d * d <= temp:
                count = 0
                while temp % (d * d) == 0:
                    temp //= (d * d)
                    count += 1
                if count > 0:
                    temp //= d
                d += 1

            # Now remove any remaining factors that appear an odd number of times
            # Actually, let's use a more direct approach
            result = 1
            for i in range(2, int(math.sqrt(num)) + 1):
                count = 0
                while num % (i * i) == 0:
                    num //= (i * i)
                    count += 1
                if count > 0:
                    result *= i
            return result

        # More efficient way: keep dividing by squares
        def get_square_free_part_efficient(num):
            result = 1
            d = 2
            while d * d <= num:
                count = 0
                while num % (d * d) == 0:
                    num //= (d * d)
                    count += 1
                if count > 0:
                    result *= d
                d += 1

            # If num > 1, it's a prime factor with exponent 1
            if num > 1:
                result *= num

            return result

        # Let's use a simpler approach: divide by squares until we can't anymore
        def get_square_free_part_simple(num):
            result = num
            d = 2
            while d * d <= result:
                while result % (d * d) == 0:
                    result //= (d * d)
                d += 1
            return result

        # Group numbers by their square-free part
        groups = defaultdict(list)

        for i, num in enumerate(nums):
            square_free = get_square_free_part_simple(num)
            groups[square_free].append(num)

        # Calculate maximum sum
        max_sum = 0
        for group in groups.values():
            max_sum = max(max_sum, sum(group))

        return max_sum

